changeSet.sql:
CREATE TABLE IF NOT EXISTS stat_snapshot
(
    stat_snapshot_id BIGSERIAL PRIMARY KEY,
    snapshot_date    TIMESTAMP NOT NULL,
    message_text     VARCHAR(1000) NOT NULL,
    total_count      BIGINT,
    bot_count        BIGINT,
    web_count        BIGINT,
    user_count       BIGINT
);
CREATE INDEX IF NOT EXISTS idx_stat_snapshot_date ON stat_snapshot(snapshot_date);
CREATE INDEX IF NOT EXISTS idx_stat_snapshot_message ON stat_snapshot(message_text);
COMMENT ON TABLE stat_snapshot IS 'Снимки статистики по командам бота';
